{
  "charges": [
    {
      "claim": "Empty keepQueryParameters array causes all query parameters to be removed, whereas base preserves them",
      "file": "index.js",
      "line": 229,
      "severity": "major",
      "witnessCode": "import { strict as assert } from 'node:assert';\nimport normalizeUrl from '../index.js';\n\nconst url = normalizeUrl('http://example.com/path?foo=bar&baz=qux', { keepQueryParameters: [] });\n\n// In base, query parameters should be preserved\nassert.match(url, /[?&]foo=bar(?=&|$)/);\nassert.match(url, /[?&]baz=qux(?=&|$)/);"
    }
  ]
}
